// The judge provides: int read4(char *buf4);
class Solution
{
public:
    int read(char*buf, int n)
    {
        int got = 0;
        char tmp[4];
        while (got < n)
        {
            int cnt = read4(tmp);
            if (!cnt)
            {
                break;
            }
            for (int i = 0; i < cnt && got < n;++i)
            {
                buf[got++] = tmp[i];
            }
        }
        return got;
    }
};
